void generate_aes_128_key(char *filePath, unsigned char *returnedKey) {
  int i;
  int part;
  FILE *fptr;
  char key[16];
  struct timespec times;
  clock_gettime(CLOCK_REALTIME, &times);
  srand(times.tv_nsec);

  for (i = 0; i < 16; i++) {
    part = (rand() % 3);
    if (part == 0) {
      key[i] = (rand() % 10) + 48;
    }

    else if (part == 1) {
      key[i] = (rand() % 26) + 65;
    }

    else if (part == 2) {
      key[i] = (rand() % 26) + 97;
    }
  }
  fptr = fopen(filePath, "w");
  for (i = 0; i < 16; i++) {
    fputc(key[i], fptr);
  }
  STRCPY((char *)returnedKey, key);
  fclose(fptr);
}

