		regulation = 0;
	else if (_rtl8812ae_eq_n_byte(pregulation, "MKK", 3))
		regulation = 1;
	else if (_rtl8812ae_eq_n_byte(pregulation, "ETSI", 4))
		regulation = 2;
	else if (_rtl8812ae_eq_n_byte(pregulation, "WW13", 4))
		regulation = 3;

